<fieldset class="border rounded p-3 mb-3" data-menu-item><legend class="float-none w-auto h6 px-1">Ligação</legend><input type="hidden" name="items[{{ $index }}][id]" value="{{ $item['id']??'__ID__' }}" data-item-id><div class="row g-2"><label class="col-md-4">Texto<input class="form-control" name="items[{{ $index }}][label]" value="{{ $item['label']??'' }}" maxlength="100" required data-item-label></label><label class="col-md-8">Endereço da página ou URL<input class="form-control" name="items[{{ $index }}][url]" value="{{ $item['url']??'' }}" placeholder="/sobre ou https://exemplo.pt" required maxlength="2000" data-item-url></label><label class="col-md-6">Superior<select class="form-select" name="items[{{ $index }}][parent]" data-item-parent data-value="{{ $item['parent']??'' }}"><option value="">Sem superior</option></select></label><label class="col-md-3">Ordem<input class="form-control" type="number" min="0" max="10000" name="items[{{ $index }}][position]" value="{{ $item['position']??0 }}" required></label><div class="col-md-3 d-flex align-items-end"><button class="btn btn-outline-danger" type="button" data-menu-remove>Remover</button></div><label class="col-12"><input type="checkbox" name="items[{{ $index }}][new_tab]" value="1" @checked($item['new_tab']??false)> Abrir num novo separador</label></div></fieldset>
